
const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];

const people = [
  {name:"marina.s",img:"https://i.pravatar.cc/100?img=47",last:"Adorei a foto!"},
    {name:"pedro_oliveira",img:"https://i.pravatar.cc/100?img=13",last:"Bora jogar sábado?"},
      {name:"ana.clara",img:"https://i.pravatar.cc/100?img=44",last:"Kkkkk verdade"},
        {name:"joaovitor",img:"https://i.pravatar.cc/100?img=59",last:"Me manda depois"}
        ];

        let posts = [
          {user:"gabriel.dev",avatar:"https://i.pravatar.cc/100?img=12",image:"https://images.unsplash.com/photo-1522778119026-d647f0596c20?w=900",likes:128,caption:"Dia de futebol! ⚽",comments:"Ver todos os 8 comentários"},
            {user:"marina.s",avatar:people[0].img,image:"https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?w=900",likes:86,caption:"Um dia bonito para guardar ✨",comments:"Ver todos os 3 comentários"},
              {user:"pedro_oliveira",avatar:people[1].img,image:"https://images.unsplash.com/photo-1519608487953-e999c86e7455?w=900",likes:203,caption:"Que vista incrível!",comments:"Ver todos os 12 comentários"},
                {user:"gabriel.dev",avatar:"https://i.pravatar.cc/100?img=12",image:"https://images.unsplash.com/photo-1517649763962-0c623066013b?w=900",likes:94,caption:"Foco e dedicação. 💪",comments:"Ver todos os 4 comentários"},
                  {user:"ana.clara",avatar:people[2].img,image:"https://images.unsplash.com/photo-1490750967868-88aa4486c946?w=900",likes:65,caption:"Flores e boas energias 🌸",comments:"Ver todos os 2 comentários"},
                    {user:"gabriel.dev",avatar:"https://i.pravatar.cc/100?img=12",image:"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=900",likes:171,caption:"Colecionando momentos.",comments:"Ver todos os 9 comentários"}
                    ];

                    const reels = [
                      ["https://images.unsplash.com/photo-1517466787929-bc90951d0974?w=600","Treino de hoje","@futebol.raiz"],
                        ["https://images.unsplash.com/photo-1500534623283-312aade485b7?w=600","Paisagens incríveis","@viajecomigo"],
                          ["https://images.unsplash.com/photo-1517649763962-0c623066013b?w=600","Movimente-se!","@sportlife"],
                            ["https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=600","Momentos especiais","@ana.clara"],
                              ["https://images.unsplash.com/photo-1506157786151-b8491531f063?w=600","Som e energia","@musicdaily"],
                                ["https://images.unsplash.com/photo-1521412644187-c49fa049e84d?w=600","Paixão pelo jogo","@bola.no.pe"]
                                ];

                                let activeChat = null;

                                function toast(msg) {
                                  const t = $("#toast");
                                    t.textContent = msg;
                                      t.classList.add("show");

                                        setTimeout(() => {
                                            t.classList.remove("show");
                                              }, 2300);
                                              }

                                              // STORIES
                                              function renderStories() {
                                                const names = [
                                                    "marina.s",
                                                        "pedro_oliveira",
                                                            "ana.clara",
                                                                "joaovitor",
                                                                    "luiza.jpg",
                                                                        "rafael_10"
                                                                          ];

                                                                            const ids = [47, 13, 44, 59, 11, 32];

                                                                              $("#stories").innerHTML =
                                                                                  '<div class="story own"><div class="story-ring"><img src="https://i.pravatar.cc/100?img=12"></div><span>Seu story</span></div>' +
                                                                                      names.map((name, i) => `
                                                                                            <div class="story">
                                                                                                    <div class="story-ring">
                                                                                                              <img src="https://i.pravatar.cc/100?img=${ids[i]}">
                                                                                                                      </div>
                                                                                                                              <span>${name}</span>
                                                                                                                                    </div>
                                                                                                                                        `).join("");
                                                                                                                                        }

                                                                                                                                        // PUBLICAÇÕES
                                                                                                                                        function renderFeed() {
                                                                                                                                          $("#feed").innerHTML = posts.map((p, i) => `
                                                                                                                                              <article class="post">

                                                                                                                                                    <div class="post-head">
                                                                                                                                                            <img src="${p.avatar}">
                                                                                                                                                                    <b>${p.user}</b>
                                                                                                                                                                            <button class="more">···</button>
                                                                                                                                                                                  </div>

                                                                                                                                                                                        <img class="post-image" src="${p.image}" alt="Publicação">

                                                                                                                                                                                              <div class="post-actions">
                                                                                                                                                                                                      <button class="action like-btn" data-index="${i}">♡</button>
                                                                                                                                                                                                              <button class="action comment-btn">♧</button>
                                                                                                                                                                                                                      <button class="action">➤</button>
                                                                                                                                                                                                                              <button class="action">♧</button>
                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                          <div class="post-content">
                                                                                                                                                                                                                                                  <div class="likes">${p.likes} curtidas</div>
                                                                                                                                                                                                                                                          <div class="caption">
                                                                                                                                                                                                                                                                    <b>${p.user}</b>${p.caption}
                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                    <div class="comments">${p.comments}</div>
                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                <div class="comment-row">
                                                                                                                                                                                                                                                                                                        <input placeholder="Adicione um comentário...">
                                                                                                                                                                                                                                                                                                                <button class="send-comment">Publicar</button>
                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                          </article>
                                                                                                                                                                                                                                                                                                                            `).join("");

                                                                                                                                                                                                                                                                                                                              // CURTIDAS
                                                                                                                                                                                                                                                                                                                                $$(".like-btn").forEach(btn => {
                                                                                                                                                                                                                                                                                                                                    btn.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                          const p = posts[Number(btn.dataset.index)];
                                                                                                                                                                                                                                                                                                                                                const liked = btn.classList.toggle("liked");

                                                                                                                                                                                                                                                                                                                                                      btn.textContent = liked ? "♥" : "♡";
                                                                                                                                                                                                                                                                                                                                                            p.likes += liked ? 1 : -1;

                                                                                                                                                                                                                                                                                                                                                                  btn.closest(".post")
                                                                                                                                                                                                                                                                                                                                                                          .querySelector(".likes").textContent =
                                                                                                                                                                                                                                                                                                                                                                                  p.likes.toLocaleString("pt-BR") + " curtidas";
                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                          // COMENTÁRIOS
                                                                                                                                                                                                                                                                                                                                                                                            $$(".send-comment").forEach(btn => {
                                                                                                                                                                                                                                                                                                                                                                                                btn.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                      const input = btn.previousElementSibling;

                                                                                                                                                                                                                                                                                                                                                                                                            if (input.value.trim()) {
                                                                                                                                                                                                                                                                                                                                                                                                                    toast("Comentário publicado!");
                                                                                                                                                                                                                                                                                                                                                                                                                            input.value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                        // SUGESTÕES DE AMIGOS
                                                                                                                                                                                                                                                                                                                                                                                                                                        function renderSuggestions() {
                                                                                                                                                                                                                                                                                                                                                                                                                                          $("#suggestionsList").innerHTML = people.map(p => `
                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="suggestion">
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <img src="${p.img}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <b>${p.name}</b>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <small>Sugestão para você</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button class="follow-btn">Seguir</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `).join("");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $$(".follow-btn").forEach(btn => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  btn.onclick = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btn.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                btn.textContent === "Seguir" ? "Seguindo" : "Seguir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      toast(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              btn.textContent === "Seguindo"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? "Agora você está seguindo!"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : "Você deixou de seguir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // REELS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function renderReels() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $("#reelsGrid").innerHTML = reels.map(r => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="reel-card" tabindex="0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <img src="${r[0]}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span class="reel-play">▶</span>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="reel-overlay">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <b>${r[1]}</b>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <small>${r[2]}</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  `).join("");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $$(".reel-card").forEach(card => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        card.onclick = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              toast("Reel de demonstração!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // PERFIL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function renderProfile() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $("#profileGrid").innerHTML = posts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .filter(p => p.user === "gabriel.dev")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .map(p => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <img src="${p.image}" alt="Publicação do perfil">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `).join("");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $("#postCount").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              posts.filter(p => p.user === "gabriel.dev").length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // CONVERSAS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function renderChats() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $("#chatList").innerHTML = people.map((p, i) => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="chat-person ${activeChat === i ? "selected" : ""}"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             data-chat="${i}">

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <img src="${p.img}">

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <b>${p.name}</b>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <small>${p.last}</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     `).join("");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       $$(".chat-person").forEach(el => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           el.onclick = () => openChat(Number(el.dataset.chat));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // ABRIR CONVERSA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             function openChat(i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               activeChat = i;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 renderChats();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const p = people[i];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     $("#chatPanel").innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <div class="chat-top">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               <img src="${p.img}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <b>${p.name}</b>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <small>Ativo(a) recentemente</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <div class="chat-messages" id="chatMessages">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <div class="bubble">Oi! Tudo bem?</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               <div class="bubble mine">${p.last}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <div class="bubble">Que legal! 😊</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <form class="chat-compose" id="chatForm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <input id="chatInput" placeholder="Mensagem..." autocomplete="off">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <button>Enviar</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $("#chatForm").onsubmit = e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     e.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const input = $("#chatInput");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (!input.value.trim()) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const message = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     message.className = "bubble mine";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         message.textContent = input.value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             $("#chatMessages").append(message);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 input.value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     $("#chatMessages").scrollTop =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           $("#chatMessages").scrollHeight;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // NAVEGAÇÃO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             function showView(view) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $$(".view").forEach(v => v.classList.add("hidden"));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $("#" + view + "View").classList.remove("hidden");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   $$(".nav-item[data-view], .mobile-nav [data-view]")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .forEach(btn => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             btn.classList.toggle("active", btn.dataset.view === view);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (view === "perfil") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       renderProfile();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         $$("[data-view]").forEach(btn => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           btn.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               showView(btn.dataset.view);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $$("[data-open-profile]").forEach(btn => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   btn.onclick = e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           showView("perfil");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             $("#mobileMessages").onclick = () => showView("mensagens");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             $("#startChat").onclick = () => openChat(0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // MODAIS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             function openModal(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $("#" + id).classList.remove("hidden");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               function closeModals() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $$(".modal").forEach(m => m.classList.add("hidden"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $("#newPostBtn").onclick = () => openModal("postModal");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $("#mobileCreate").onclick = () => openModal("postModal");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $$(".close-modal").forEach(btn => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   btn.onclick = closeModals;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   $$(".modal").forEach(modal => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     modal.addEventListener("click", e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (e.target === modal) closeModals();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // PRÉVIA DA IMAGEM
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           $("#imageUrl").addEventListener("input", e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const url = e.target.value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $("#uploadPreview").innerHTML = url
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ? `<img src="${url}" alt="Prévia da publicação">`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       : '＋<span>Adicione uma imagem por URL</span>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // CRIAR PUBLICAÇÃO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       $("#sharePost").onclick = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const image = $("#imageUrl").value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const caption = $("#caption").value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (!image) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 toast("Cole a URL de uma imagem primeiro.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         posts.unshift({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             user: "gabriel.dev",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 avatar: "https://i.pravatar.cc/100?img=12",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     image: image,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         likes: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             caption: caption || "Nova publicação ✨",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 comments: "Seja o primeiro a comentar"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     renderFeed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       renderProfile();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         $("#imageUrl").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           $("#caption").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             $("#uploadPreview").innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 '＋<span>Adicione uma imagem por URL</span>';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   closeModals();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     showView("inicio");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       toast("Sua publicação foi compartilhada!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // EDITAR PERFIL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       $("#editProfile").onclick = () => openModal("editModal");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       $("#saveProfile").onclick = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const name = $("#editName").value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const bio = $("#editBio").value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (name) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $("#perfilView .profile-info > b").textContent = name;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     $("#perfilView .profile-info p").innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         bio.replace(/\n/g, "<br>");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           closeModals();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             toast("Perfil atualizado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // INICIAR O PROJETO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             renderStories();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             renderFeed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             renderSuggestions();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             renderReels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             renderChats();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             renderProfile();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             